ALTER TABLE public.fincommand_companies ADD COLUMN zoho_organization_id text;
CREATE UNIQUE INDEX fincommand_company_zoho_org ON public.fincommand_companies(zoho_organization_id) WHERE zoho_organization_id IS NOT NULL;
CREATE TABLE public.fincommand_sync_resources (company_id uuid NOT NULL REFERENCES public.fincommand_companies(id),resource text NOT NULL,path text NOT NULL,response_key text NOT NULL,id_key text NOT NULL,detail_key text,page integer NOT NULL DEFAULT 1,phase text NOT NULL DEFAULT 'list',status text NOT NULL DEFAULT 'pending',records_pulled integer NOT NULL DEFAULT 0,detail_cursor text,last_error text,http_status integer,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,resource));
GRANT SELECT ON public.fincommand_sync_resources TO authenticated; GRANT ALL ON public.fincommand_sync_resources TO service_role;
ALTER TABLE public.fincommand_sync_resources ENABLE ROW LEVEL SECURITY;
CREATE POLICY fincommand_sync_read ON public.fincommand_sync_resources FOR SELECT TO authenticated USING(public.fincommand_can_read_company(company_id));
CREATE TABLE public.fincommand_source_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.fincommand_companies(id),resource text NOT NULL,request_path text NOT NULL,page integer,payload jsonb NOT NULL,fetched_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.fincommand_source_snapshots TO authenticated; GRANT ALL ON public.fincommand_source_snapshots TO service_role;
ALTER TABLE public.fincommand_source_snapshots ENABLE ROW LEVEL SECURITY;
CREATE POLICY fincommand_snapshot_read ON public.fincommand_source_snapshots FOR SELECT TO authenticated USING(public.fincommand_can_read_company(company_id));
CREATE INDEX fincommand_snapshot_resource ON public.fincommand_source_snapshots(company_id,resource,fetched_at);
CREATE TABLE public.fincommand_source_records (company_id uuid NOT NULL REFERENCES public.fincommand_companies(id),resource text NOT NULL,source_id text NOT NULL,payload jsonb NOT NULL,detail_complete boolean NOT NULL DEFAULT false,source_modified_at text,fetched_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,resource,source_id));
GRANT SELECT ON public.fincommand_source_records TO authenticated; GRANT ALL ON public.fincommand_source_records TO service_role;
ALTER TABLE public.fincommand_source_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY fincommand_source_read ON public.fincommand_source_records FOR SELECT TO authenticated USING(public.fincommand_can_read_company(company_id));
CREATE TABLE public.fincommand_documents (company_id uuid NOT NULL REFERENCES public.fincommand_companies(id),resource text NOT NULL,source_id text NOT NULL,document_number text,document_date date,due_date date,party_source_id text,party_name text,status text,currency text,base_currency text NOT NULL,exchange_rate numeric,total numeric,subtotal numeric,tax_total numeric,balance_due numeric,total_base numeric,balance_base numeric,location_id text,project_id text,normalization_issues jsonb NOT NULL DEFAULT '[]',fetched_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,resource,source_id),FOREIGN KEY(company_id,resource,source_id) REFERENCES public.fincommand_source_records(company_id,resource,source_id));
GRANT SELECT ON public.fincommand_documents TO authenticated; GRANT ALL ON public.fincommand_documents TO service_role;
ALTER TABLE public.fincommand_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY fincommand_document_read ON public.fincommand_documents FOR SELECT TO authenticated USING(public.fincommand_can_read_company(company_id));
CREATE INDEX fincommand_document_date ON public.fincommand_documents(company_id,document_date,resource);
CREATE TABLE public.fincommand_document_lines (company_id uuid NOT NULL,resource text NOT NULL,source_id text NOT NULL,line_id text NOT NULL,item_id text,account_id text,description text,quantity numeric,rate numeric,amount numeric,tax_id text,project_id text,payload jsonb NOT NULL,PRIMARY KEY(company_id,resource,source_id,line_id),FOREIGN KEY(company_id,resource,source_id) REFERENCES public.fincommand_source_records(company_id,resource,source_id));
GRANT SELECT ON public.fincommand_document_lines TO authenticated; GRANT ALL ON public.fincommand_document_lines TO service_role;
ALTER TABLE public.fincommand_document_lines ENABLE ROW LEVEL SECURITY;
CREATE POLICY fincommand_line_read ON public.fincommand_document_lines FOR SELECT TO authenticated USING(public.fincommand_can_read_company(company_id));
CREATE TABLE public.fincommand_masters (company_id uuid NOT NULL,resource text NOT NULL,source_id text NOT NULL,name text,kind text,status text,currency text,payload jsonb NOT NULL,PRIMARY KEY(company_id,resource,source_id),FOREIGN KEY(company_id,resource,source_id) REFERENCES public.fincommand_source_records(company_id,resource,source_id));
GRANT SELECT ON public.fincommand_masters TO authenticated; GRANT ALL ON public.fincommand_masters TO service_role;
ALTER TABLE public.fincommand_masters ENABLE ROW LEVEL SECURITY;
CREATE POLICY fincommand_master_read ON public.fincommand_masters FOR SELECT TO authenticated USING(public.fincommand_can_read_company(company_id));
CREATE FUNCTION public.fincommand_store_zoho_batch(p_company uuid,p_resource text,p_records jsonb,p_documents jsonb,p_masters jsonb,p_lines jsonb,p_snapshot jsonb,p_path text,p_page integer,p_detail boolean) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN
INSERT INTO public.fincommand_source_snapshots(company_id,resource,request_path,page,payload) VALUES(p_company,p_resource,p_path,p_page,p_snapshot);
INSERT INTO public.fincommand_source_records(company_id,resource,source_id,payload,detail_complete,source_modified_at) SELECT p_company,p_resource,x->>'source_id',x->'payload',p_detail,x->>'source_modified_at' FROM jsonb_array_elements(p_records)x ON CONFLICT(company_id,resource,source_id) DO UPDATE SET payload=CASE WHEN EXCLUDED.detail_complete OR NOT fincommand_source_records.detail_complete THEN EXCLUDED.payload ELSE fincommand_source_records.payload END,detail_complete=fincommand_source_records.detail_complete OR EXCLUDED.detail_complete,source_modified_at=EXCLUDED.source_modified_at,fetched_at=now();
INSERT INTO public.fincommand_documents SELECT * FROM jsonb_populate_recordset(null::public.fincommand_documents,p_documents) ON CONFLICT(company_id,resource,source_id) DO UPDATE SET document_number=EXCLUDED.document_number,document_date=EXCLUDED.document_date,due_date=EXCLUDED.due_date,party_source_id=EXCLUDED.party_source_id,party_name=EXCLUDED.party_name,status=EXCLUDED.status,currency=EXCLUDED.currency,base_currency=EXCLUDED.base_currency,exchange_rate=EXCLUDED.exchange_rate,total=EXCLUDED.total,subtotal=EXCLUDED.subtotal,tax_total=EXCLUDED.tax_total,balance_due=EXCLUDED.balance_due,total_base=EXCLUDED.total_base,balance_base=EXCLUDED.balance_base,location_id=EXCLUDED.location_id,project_id=EXCLUDED.project_id,normalization_issues=EXCLUDED.normalization_issues,fetched_at=now();
INSERT INTO public.fincommand_masters SELECT * FROM jsonb_populate_recordset(null::public.fincommand_masters,p_masters) ON CONFLICT(company_id,resource,source_id) DO UPDATE SET name=EXCLUDED.name,kind=EXCLUDED.kind,status=EXCLUDED.status,currency=EXCLUDED.currency,payload=EXCLUDED.payload;
IF p_detail THEN DELETE FROM public.fincommand_document_lines WHERE company_id=p_company AND resource=p_resource AND source_id IN(SELECT x->>'source_id' FROM jsonb_array_elements(p_records)x); END IF;
INSERT INTO public.fincommand_document_lines SELECT * FROM jsonb_populate_recordset(null::public.fincommand_document_lines,p_lines) ON CONFLICT(company_id,resource,source_id,line_id) DO UPDATE SET payload=EXCLUDED.payload,amount=EXCLUDED.amount,quantity=EXCLUDED.quantity,rate=EXCLUDED.rate;
END; $$;
REVOKE ALL ON FUNCTION public.fincommand_store_zoho_batch(uuid,text,jsonb,jsonb,jsonb,jsonb,jsonb,text,integer,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.fincommand_store_zoho_batch(uuid,text,jsonb,jsonb,jsonb,jsonb,jsonb,text,integer,boolean) TO service_role;
COMMENT ON TABLE public.fincommand_documents IS 'Source document gross totals include tax and are not recognized revenue. Unknown FX is NULL. Never derive audited P&L or balance sheets from documents alone.';
COMMENT ON TABLE public.fincommand_source_snapshots IS 'Immutable source response archive for provenance and future reprocessing; protected by company membership.';